<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM smes WHERE id=? AND status="active"');$s->execute([$id]);$store=$s->fetch();if(!$store){http_response_code(404);exit('Store not found.');}$s=$pdo->prepare("SELECT p.id,p.name,p.slug,p.price,p.stock_quantity,? AS sme_business_name,? AS sme_trust_score,NULL AS primary_image FROM products p WHERE p.sme_id=? AND p.status='active' ORDER BY p.created_at DESC");$s->execute([$store['business_name'],$store['trust_score'],$id]);$products=$s->fetchAll();$pageTitle=$store['business_name'];include __DIR__.'/../includes/partials/header.php';?><h1><?=e($store['business_name'])?></h1><p><?=e($store['description'])?></p><p><?=e($store['district'])?> · Trust Score <?=number_format((float)$store['trust_score'],0)?>/100</p><div class="product-grid"><?php foreach($products as $product)include __DIR__.'/../includes/partials/product_card.php';?></div><?php include __DIR__.'/../includes/partials/footer.php';?>